const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const builtins=[{id:'brown',title:'夜色里的低语',scene:'睡眠',type:'local',desc:'柔和棕噪音 · 本地合成',icon:'☾'},{id:'pink',title:'风经过窗边',scene:'放松',type:'local',desc:'轻柔滤波噪音 · 本地合成',icon:'≈'},{id:'white',title:'留白的午后',scene:'专注',type:'local',desc:'均匀白噪音 · 本地合成',icon:'◌'}];
let saved=[];try{saved=JSON.parse(localStorage.getItem('murmur-sounds')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(x=>x&&typeof x.title==='string'&&typeof x.url==='string'&&/^https?:\/\//i.test(x.url))}catch{}let page='home',filter='全部',query='',current=null,playing=false,ctx,source,gain,endAt=0,volume=.35;
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(notify.t);notify.t=setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){try{localStorage.setItem('murmur-sounds',JSON.stringify(saved));return true}catch{notify('设备存储不可用，暂时无法保存');return false}}
function all(){return [...builtins,...saved]}function cards(items){return items.length?items.map(s=>`<article class="sound"><div class="art">${esc(s.icon||'↗')}</div><button class="sound-info" data-sound="${esc(s.id)}"><strong>${esc(s.title)}</strong><small>${esc(s.scene)} · ${esc(s.type==='local'?s.desc:'外部收藏 · 原平台收听')}</small></button><button class="play" data-sound="${esc(s.id)}" aria-label="打开${esc(s.title)}">${s.type==='local'?'▷':'↗'}</button>${s.type==='external'?`<button class="delete" data-delete="${esc(s.id)}" aria-label="删除${esc(s.title)}">×</button>`:''}</article>`).join(''):'<div class="empty"><p>这里还很安静</p><button class="pill" data-add>添加第一条收藏 ＋</button></div>'}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const m=$('#main');if(page==='home'){m.innerHTML=`<div class="eyebrow">A LITTLE SPACE TO UNWIND</div><h1>留一点安静，<br>给此刻的自己。</h1><p style="font-size:12px;margin-bottom:25px">不必急着调整状态，先听一会儿。</p><section class="hero"><div class="eyebrow">TONIGHT'S QUIET MOMENT</div><h1>把今天，<br>轻轻放下。</h1><p>让柔和的声音填满房间，<br>剩下的，留给明天。</p><button class="pill" data-sound="brown">▷ 开始一段安静</button></section><div class="section-head"><h2>此刻，想去哪里？</h2><span>随你的节奏</span></div><div class="scenes">${[['☾','睡眠','慢慢进入夜晚'],['◌','专注','找回自己的节奏'],['≈','放松','给思绪留点空隙']].map(([i,t,d])=>`<button class="scene" data-scene="${t}"><b>${i}</b><strong>${t}</strong><small>${d}</small></button>`).join('')}</div><div class="section-head"><h2>为你留住的声音</h2><button data-library style="color:var(--muted);font-size:11px">全部声音 ↗</button></div><div class="sound-list">${cards([...saved.slice(-2).reverse(),...builtins].slice(0,4))}</div><p class="quote">世界很大，这里只需要容下你。</p>`}else if(page==='library'){m.innerHTML=`<div class="eyebrow">YOUR SOUND COLLECTION</div><h1>喜欢的声音，<br>都在这里。</h1><p style="font-size:12px">按此刻的心情，找到熟悉的陪伴。</p><input class="search" id="search" aria-label="搜索声音" placeholder="搜索声音名称…" value="${esc(query)}"><div class="filters">${['全部','睡眠','专注','放松'].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t}</button>`).join('')}</div><div class="sound-list" id="results">${libraryCards()}</div><button class="pill" data-add style="margin-top:25px">＋ 添加声音链接</button>`;$('#search').oninput=e=>{query=e.target.value;$('#results').innerHTML=libraryCards()}}else{m.innerHTML=`<div class="eyebrow">A SPACE OF YOUR OWN</div><h1>我的小小空间</h1><div class="profile-box"><h2>${saved.length} 条声音收藏</h2><p>收藏只保存在当前浏览器，暂不跨设备同步。清除浏览器数据会移除收藏，建议定期导出。</p><button id="export">导出收藏备份 ↓</button></div><div class="profile-box"><h2>在 iPhone 上使用</h2><p>在 Safari 打开本站，点击分享按钮，选择“添加到主屏幕”，就能更方便地回到这里。</p></div><div class="profile-box"><h2>关于这一版</h2><p>Murmur 0.1 · 可交互 MVP<br>内置声音由设备本地合成；外部收藏跳转原平台。网页锁屏和后台播放、定时效果仍需在你的 iPhone 上验证。</p><p>不提供睡眠诊断，也不承诺改善失眠。</p></div>`;$('#export').onclick=()=>{let u=URL.createObjectURL(new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='murmur-collections.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}}}
function libraryCards(){return cards(all().filter(x=>(filter==='全部'||x.scene===filter)&&x.title.toLowerCase().includes(query.toLowerCase())))}
function halt(){if(source){try{source.stop()}catch{}source.disconnect();source=null}playing=false;updatePlayer()}
async function start(){if(!current||current.type!=='local')return;try{ctx??=new (window.AudioContext||window.webkitAudioContext)();await ctx.resume();const len=ctx.sampleRate*8,buffer=ctx.createBuffer(1,len,ctx.sampleRate),data=buffer.getChannelData(0);let brown=0;for(let i=0;i<len;i++){const n=Math.random()*2-1;brown=(brown+.02*n)/1.02;data[i]=current.id==='brown'?brown*3.5:current.id==='pink'?brown*2+n*.12:n*.3}source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;gain=ctx.createGain();gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(volume,ctx.currentTime+1);source.connect(gain);gain.connect(ctx.destination);source.start();playing=true;updatePlayer()}catch{notify('声音暂时无法启动，请再次点击播放');halt()}}
function updatePlayer(){if(!current)return;$('#mini').hidden=false;$('#mini').innerHTML=`<div class="art">${esc(current.icon||'↗')}</div><button class="mini-open" data-expand>${esc(current.title)}<small>${current.type==='external'?'外部收藏 · 原平台收听':playing?'正在播放 · 本地合成':'已暂停 · 本地合成'}</small></button><button class="play" ${current.type==='local'?'data-toggle':'data-expand'} aria-label="${playing?'暂停':'打开播放页'}">${current.type==='external'?'↗':playing?'Ⅱ':'▷'}</button>`;$('#playerTitle').textContent=current.title;$('#playerStatus').textContent=current.type==='external'?'外部收藏 · 播放状态由原平台管理':playing?'正在播放 · 慢慢呼吸':'已暂停';$('#controls').hidden=current.type!=='local';$('#external').hidden=current.type!=='external';if(current.type==='external')$('#external').href=current.url;$('#toggle').textContent=playing?'暂停':'继续播放';$('#playerNote').textContent=current.type==='external'?'返回 Murmur 后能否继续收听，取决于原平台。这里无法控制原平台进度、音量或定时停止。':'内置环境底噪由本地合成。定时结束前 10 秒渐弱；锁屏或后台时的表现受浏览器限制。'}
document.addEventListener('click',async e=>{let b=e.target.closest('button,a');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0)}if(b.hasAttribute('data-library')){page='library';filter='全部';render();window.scrollTo(0,0)}if(b.dataset.scene){page='library';filter=b.dataset.scene;render();window.scrollTo(0,0)}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.hasAttribute('data-add')||b.id==='addTop'){$('#formError').textContent='';$('#add').showModal()}if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.sound){const next=all().find(s=>s.id===b.dataset.sound);if(!next)return;if(current?.id!==next.id){halt();endAt=0;$('#timer').value='0';current=next}updatePlayer();$('#player').showModal();if(current.type==='local'&&!playing)await start()}if(b.hasAttribute('data-expand'))$('#player').showModal();if(b.hasAttribute('data-toggle')||b.id==='toggle'){if(playing)halt();else await start()}if(b.dataset.delete){let idx=saved.findIndex(s=>s.id===b.dataset.delete);if(idx<0)return;const old=[...saved];saved.splice(idx,1);if(!persist()){saved=old;return}if(current?.id===b.dataset.delete){halt();current=null;$('#mini').hidden=true}render();notify('已移除收藏')}});
$('#addForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let url;try{url=new URL(f.get('url'));if(!['http:','https:'].includes(url.protocol))throw Error()}catch{$('#formError').textContent='请填写有效的 http 或 https 链接';return}if(saved.some(s=>s.url===url.href)){$('#formError').textContent='这个链接已经在声音库里了';return}const title=f.get('title').trim();if(!title){$('#formError').textContent='请填写声音名称';return}saved.push({id:'saved-'+Date.now(),title,url:url.href,scene:f.get('scene'),type:'external',icon:'↗'});if(!persist()){saved.pop();return}e.target.reset();$('#add').close();render();notify('已收藏，喜欢的声音不会散落了')};
$('#volume').oninput=e=>{volume=Number(e.target.value);if(gain&&playing)gain.gain.setTargetAtTime(volume,ctx.currentTime,.1)};$('#timer').onchange=e=>{endAt=Number(e.target.value)?Date.now()+Number(e.target.value)*60000:0;if(gain&&playing)gain.gain.setTargetAtTime(volume,ctx.currentTime,.2)};
setInterval(()=>{if(!endAt){$('#timerStatus').textContent='';return}let left=endAt-Date.now();if(left<=0){halt();endAt=0;$('#timer').value='0';$('#timerStatus').textContent='定时已结束';return}$('#timerStatus').textContent=`${Math.ceil(left/60000)} 分钟后停止`;if(left<10000&&playing&&gain)gain.gain.setTargetAtTime(volume*left/10000,ctx.currentTime,.2)},500);render();
